function validate([a, b, c]) {
  for (const [name, values] of [['a', a], ['b', b], ['c', c]]) {
    if (values.length < 1 || values.length > 100) return `${name} needs 1 to 100 values.`;
    if (values.some(v => v < 0 || v > 100)) return `Each value of ${name} is between 0 and 100.`;
  }
  return null;
}

