function tripletCount(a, b, c) {
  const countParities = (values) => {
    const counts = [0, 0];
    for (const value of values) {
      let parity = 0;
      for (let rest = value; rest > 0; rest >>= 1) {
        parity ^= rest & 1;
      }
      counts[parity]++;
    }
    return counts;
  };
  const countA = countParities(a);
  const countB = countParities(b);
  const countC = countParities(c);
  let total = 0;
  for (let p = 0; p < 2; p++) {
    for (let q = 0; q < 2; q++) {
      total += countA[p] * countB[q] * countC[p ^ q];
    }
  }
  return total;
}

