function tripletCount(a, b, c) {
  // Try every triplet and count the 1 characters of its XOR written in base 2.
  let good = 0;
  for (let i = 0; i < a.length; i++)
    for (let j = 0; j < b.length; j++)
      for (let k = 0; k < c.length; k++) {
        const ones = (a[i] ^ b[j] ^ c[k]).toString(2).split('').filter(ch => ch === '1').length;
        if (ones % 2 === 0) good++;
      }
  return good;
}

