function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Small inputs sometimes use a tiny value range so that values and parities repeat.
  const top = size === 'large' ? 100 : [1, 3, 7, 100][int(0, 3)];
  const make = () => {
    const length = size === 'large' ? int(90, 100) : int(1, 5);
    return Array.from({ length }, () => int(0, top));
  };
  return [make(), make(), make()];
}
